from typing import Callable

from speech_models import StreamingRecognitionResponse

def handle_partial_and_final_results(
    responses: StreamingRecognitionResponse,
    partial_callback: Callable[[str], None],
    final_callback: Callable[[str], None]
):
    """Handles partial and final streaming recognition events."""

    for response in responses:
        if not response.results: 
            continue

        result = response.results[0]
        if not result.alternatives: 
            continue

        transcript = result.alternatives[0].transcript

        if result.is_final:
            final_callback(transcript)
        else:
            partial_callback(transcript)

from dataclasses import dataclass
from google.cloud import speech_v1p1beta1 as speech
from google.protobuf.json_format import MessageToDict, ParseDict

@dataclass
class StreamingRecognitionConfig:
    config: speech.RecognitionConfig
    interim_results: bool = False
    single_utterance: bool = False

    def to_proto(self) -> speech.StreamingRecognizeRequest:
        return speech.StreamingRecognizeRequest(
            streaming_config=speech.StreamingRecognitionConfig(
                config=self.config,
                interim_results=self.interim_results,
                single_utterance=self.single_utterance,
            )
        )

@dataclass
class StreamingRecognitionResponse:
    results: list # Simplified for example; can be more detailed with nested dataclasses
    speech_event_type: int

    @classmethod
    def from_proto(cls, proto: speech.StreamingRecognizeResponse):
        # Convert protobuf message to dictionary for easier dataclass initialization
        data = MessageToDict(proto, preserving_proto_field_name=True)
        return cls(
            results=data.get("results", []),
            speech_event_type=data.get("speech_event_type", 0)
        )

from google.cloud import language_v1

def check_caption_safety(text: str) -> dict:
    """Checks live transcript text for unsafe content using Google Cloud Natural Language AI."""

    client = language_v1.LanguageServiceClient()

    document = language_v1.Document(
        content=text, type=language_v1.Document.Type.PLAIN_TEXT
    )

    # Available categories: https://cloud.google.com/natural-language/docs/moderating-content
    response = client.moderate_text(document=document)

    safety_scores = {}
    for category_filter in response.moderation_categories:
        safety_scores[category_filter.name] = category_filter.score

    return safety_scores
